$source=dirname(__DIR__);$root=sys_get_temp_dir().'/ruethies-article-preview-'.bin2hex(random_bytes(5));$public=$root.'/public_html';$process=null;
function article_preview_remove(string $p):void{if(is_link($p)||!is_dir($p)){if(file_exists($p)||is_link($p))unlink($p);return;}foreach(scandir($p)as$n)if($n!=='.'&&$n!=='..')article_preview_remove($p.'/'.$n);rmdir($p);}
