 foreach(['index.php','index.html','styles.css','profile.css','profile.js','articles.css','articles.js','order-story.css','order-story.js','carousel.js','faq.json','atmosphere.json','menu.json','404.html','manifest.json']as$file)copy($source.'/'.$file,$public.'/'.$file);
