 define('RUETHIES_PUBLIC_RENDER',true);require $public.'/admin/catalog.php';file_put_contents($public.'/menu.json',catalog_json(catalog_metadata(catalog_read_json($public.'/menu.json'),filemtime($source.'/menu.json'))));
 require $public.'/public-lib/articles.php';$state=article_empty();$state['enabled']=true;$now=gmdate('Y-m-d\TH:i:s\Z');$rows=require $public.'/admin/article-seeds.php';foreach($rows as$seed)$state['items'][]=$seed+['status'=>'draft','createdAt'=>$now,'updatedAt'=>$now,'publishedAt'=>null,'createdBy'=>'Demo owner','updatedBy'=>'Demo owner','cover'=>'','coverAlt'=>'','lang'=>'id','translationOf'=>'','deletedAt'=>null];
 for($i=1;$i<=14;$i++)$state['items'][]=['id'=>'demo-'.$i,'title'=>'Panduan uji lokal '.$i,'slug'=>'panduan-uji-lokal-'.$i,'description'=>'Konten fixture untuk meninjau tipografi, kategori, dan navigasi artikel. Tidak dipublikasikan pada hosting.','category'=>$i%2?'panduan':'ide-acara','body'=>"## Pilih sajian\n\nIni adalah konten **uji lokal** untuk melihat tampilan bacaan. Buka [Menu](/menu/) untuk melihat navigasi yang tersedia.\n\n## Siapkan kebutuhan\n\n- Jumlah\n- Tanggal kebutuhan\n\n> Kutipan demonstrasi.\n\n## Hubungi tim\n\n| Keterangan | Nilai contoh |\n| --- | --- |\n| Lingkungan | Fixture lokal |",'status'=>'published','createdAt'=>$now,'updatedAt'=>$now,'publishedAt'=>$now,'createdBy'=>'Demo owner','updatedBy'=>'Demo owner','cover'=>'','coverAlt'=>'','lang'=>'id','translationOf'=>'','deletedAt'=>null,'related'=>['/menu/','/snack-box-cikarang/']];
 article_state_validate($state);file_put_contents($root.'/ruethies-data/articles.json',json_encode($state));$users=[];foreach(['owner','staff']as$role)$users[]=['name'=>$role,'role'=>$role,'hash'=>password_hash('Local-articles-preview-2026',PASSWORD_DEFAULT),'totp'=>'','auth_version'=>str_repeat($role==='owner'?'a':'b',64),'last_totp_counter'=>-1];file_put_contents($root.'/ruethies-data/users.json',json_encode($users));
